input.command:
ls ~/.claude/projects/; f=$(ls -t ~/.claude/projects/*/*.jsonl | head -1); echo "latest: $f"; grep -m2 '"name":"Bash"' "$f" | python3 -c '
import sys,json
for line in sys.stdin:
    d=json.loads(line)
    print({k:d.get(k) for k in ("type","cwd","sessionId","timestamp","gitBranch")})
    for c in d["message"]["content"]:
        if isinstance(c,dict) and c.get("type")=="tool_use": print("  tool_use:",c["name"],c["input"].get("command","")[:80])
'

python3 - <<'EOF'
import json
p="/home/tarek/.claude/projects/-home-tarek-Projects-mech-interp-neel-application-mech-interp-2/c4174914-2c34-4291-bc45-40b48eacc19b.jsonl"
for line in open(p):
    d=json.loads(line)
    if d.get("type")!="assistant": continue
    for c in d["message"].get("content",[]):
        if isinstance(c,dict) and c.get("type")=="tool_use" and c.get("name")=="Bash" and "checkout" in c["input"].get("command",""):
            print(d["timestamp"], "branch:", d.get("gitBranch")); print(c["input"]["command"]); print("-----")
