  "PreToolUse":  ((.hooks.PreToolUse  // []) + [{"matcher":"Bash","hooks":[{"type":"command","command":"python3 /home/tarek/.claude/hooks/branch-watch.py hook","timeout":10}]}]),
  "PostToolUse": ((.hooks.PostToolUse // []) + [{"matcher":"Bash","hooks":[{"type":"command","command":"python3 /home/tarek/.claude/hooks/branch-watch.py hook","timeout":10}]}])
})' ~/.claude/settings.json > ~/.claude/settings.json.tmp && mv ~/.claude/settings.json.tmp ~/.claude/settings.json && echo "--- validate ---" && jq -e '.hooks.PreToolUse[] , .hooks.PostToolUse[] | select(.matcher=="Bash") | .hooks[] | select(.type=="command") | .command' ~/.claude/settings.json && echo "--- full file ---" && cat ~/.claude/settings.json

